class Solution {
public:
    int minDeletion(vector<int>& nums) {
        int deleted = 0;
        int n = nums.size();
        for (int i = 0; i < n - 1; i++) {
            if ((i - deleted) % 2 == 0 && nums[i] == nums[i + 1]) {
                deleted++;
            }
        }
        if ((n - deleted) % 2 == 1) {
            deleted++;
        }
        return deleted;
    }
};

class Solution {
    public int minDeletion(int[] nums) {
        int deleted = 0;
        int n = nums.length;
        for (int i = 0; i < n - 1; i++) {
            if ((i - deleted) % 2 == 0 && nums[i] == nums[i + 1]) {
                deleted++;
            }
        }
        if ((n - deleted) % 2 == 1) {
            deleted++;
        }
        return deleted;
    }
}

