var minDeletion = function(nums) {
    let deleted = 0;
    const n = nums.length;
    for (let i = 0; i < n - 1; i++) {
        if ((i - deleted) % 2 === 0 && nums[i] === nums[i + 1]) {
            deleted++;
        }
    }
    if ((n - deleted) % 2 === 1) {
        deleted++;
    }
    return deleted;
};
